@namespace sv_8a1bda82530a436196df4bce9c67b7db.Components.Pages.Board

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge @GetPriorityClass()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>

    <div class="task-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move-left" @onclick="() => OnMoveLeft.InvokeAsync(Task)">Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move-right" @onclick="() => OnMoveRight.InvokeAsync(Task)">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }

    private string GetPriorityClass() => Task.Priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };
}

@namespace sv_8a1bda82530a436196df4bce9c67b7db.Components.Pages.Board

@if (IsVisible)
{
    <div class="add-task-form">
        <input type="text" placeholder="Title" @bind="Title" />
        <input type="text" placeholder="Assignee" @bind="Assignee" />
        <select @bind="Priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
        <input type="date" @bind="DueDate" />
        <div class="form-actions">
            <button class="btn-save" @onclick="Save">Save</button>
            <button class="btn-cancel" @onclick="Cancel">Cancel</button>
        </div>
    </div>
}

@code {
    [Parameter] public bool IsVisible { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string Title { get; set; } = "";
    private string Assignee { get; set; } = "";
    private string Priority { get; set; } = "Medium";
    private DateTime DueDate { get; set; } = DateTime.Today;

    private async Task Save()
    {
        if (!string.IsNullOrWhiteSpace(Title) && !string.IsNullOrWhiteSpace(Assignee))
        {
            await OnSave.InvokeAsync((Title, Assignee, Priority, DueDate));
            ResetForm();
        }
    }

    private async Task Cancel()
    {
        ResetForm();
        await OnCancel.InvokeAsync();
    }

    private void ResetForm()
    {
        Title = "";
        Assignee = "";
        Priority = "Medium";
        DueDate = DateTime.Today;
    }
}

@namespace sv_8a1bda82530a436196df4bce9c67b7db.Components.Pages.Board

<div class="board-stats">
    <span class="stat-item">Total: @Tasks.Count</span>
    <span class="stat-item">To Do: @Tasks.Count(t => t.Status == "To Do")</span>
    <span class="stat-item">In Progress: @Tasks.Count(t => t.Status == "In Progress")</span>
    <span class="stat-item">Done: @Tasks.Count(t => t.Status == "Done")</span>
    <span class="stat-item stat-overdue">Overdue: @Tasks.Count(t => t.DueDate < DateTime.Today)</span>
</div>

@code {
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
}

@namespace sv_8a1bda82530a436196df4bce9c67b7db.Components.Pages.Board

<div class="board-search">
    <input type="text" placeholder="Search tasks by title..." value="@SearchTerm"
           @oninput="OnInput" />
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = "";
    [Parameter] public EventCallback<string> SearchTermChanged { get; set; }

    private async Task OnInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await SearchTermChanged.InvokeAsync(value);
    }
}

@namespace sv_8a1bda82530a436196df4bce9c67b7db.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName (@Tasks.Count)</h3>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>

    @if (!ShowAddForm)
    {
        <button class="btn-add-task" @onclick="() => ShowAddForm = true">Add Task</button>
    }

    <AddTaskForm IsVisible="ShowAddForm"
                 OnSave="HandleSave"
                 OnCancel="() => ShowAddForm = false" />
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnAddTask { get; set; }

    private bool ShowAddForm { get; set; }

    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) formData)
    {
        await OnAddTask.InvokeAsync(formData);
        ShowAddForm = false;
    }
}

